//
// Forward (FAInfer) kernel dispatch, isolated into per-(dtype, layout)
// translation units under autogen/ (generated by autogen/generate_kernels.py)
// so the SplitFuse::FAInfer template instantiations
// (2 dtype x {paged/non-paged with flash-decode variants} x {causal/no-mask}
// x {TND/BSND/BNSD}) compile in parallel across cores. flash_api.cpp computes
// all host-side setup (tiling, workspace, layout, block-table/mask pointers)
// and hands the raw device pointers / scalars to launch_fwd<kLayout>().
//
// head_dim is NOT a generation axis: the forward does not bin by head_dim (it
// is a runtime tiling value). The compile-time axes are dtype and kLayout only.
//
// This header stays lightweight (only the AscendC kernel_operator.h types and
// the inputLayout enum) so flash_api.cpp can include it without dragging in the
// heavy CATLASS kernel templates. kernel_operator.h must come first: kernel_common.hpp
// uses GM_ADDR / __aicore__ without including it itself.

#pragma once

#include <cstdint>
#include "tilingdata.h"
#include "acl/acl.h"
#include "kernel_operator.h"
#include "kernel_common.hpp"

struct FwdLaunchArgs {
    uint32_t launchBlockDim;
    aclrtStream aclStream;
    uint64_t fftsAddr;
    bool is_bf16;
    bool paged_KV;
    bool is_causal;
    bool is_local; // sliding-window attention (MASK_SWA)
    bool has_softcap;
    bool mlaDecodeGemv = false;
    KernelCommon::FaiKenel::inputLayout layout; // BSND, TND or BNSD
    // BNSD only: the allocated KV sequence length (S_alloc = k.size(2)), i.e. the
    // KV head-plane stride in tokens. 0 for BSND / TND.
    int64_t kv_seqlen_allocated;
    uint8_t* qDevice;
    uint8_t* kDevice;
    uint8_t* vDevice;
    uint8_t* kNewDevice;       // may be nullptr when append-KV is disabled
    uint8_t* vNewDevice;       // may be nullptr when append-KV is disabled
    uint8_t* maskDevice;       // may be nullptr when is_causal is false
    uint8_t* blockTableDevice; // may be nullptr when paged_KV is false
    uint8_t* oDevice;
    uint8_t* softmaxLseDevice;
    uint8_t* qSeqDevice;
    uint8_t* kvSeqDevice;
    uint8_t* workspaceDevice;
    FAInferTilingParams tiling;
    uint8_t* sequsedQDevice;  // per-batch used Q lengths; nullptr when absent
    uint8_t* sequsedKVDevice; // per-batch used KV lengths; nullptr when absent
    uint8_t* qvDevice;
};

// Per-(dtype, layout) implementation, defined in autogen/fwd_dispatch_<dtype>_<layout>.cpp
// via fwd_dispatch_impl.hpp. Each TU instantiates one launch_fwd_dtype<DType, kLayout>.
template <typename DType, KernelCommon::FaiKenel::inputLayout kLayout>
void launch_fwd_dtype(const FwdLaunchArgs& a);

// Runtime entry: kLayout (BSND / TND / BNSD) is fixed at the call site, then the
// matching dtype's launcher is selected. launch_fwd_dtype is explicitly
// instantiated per (dtype, kLayout) in the autogen TUs.
template <KernelCommon::FaiKenel::inputLayout kLayout>
inline void launch_fwd(const FwdLaunchArgs& a)
{
    if (a.is_bf16) {
        launch_fwd_dtype<bfloat16_t, kLayout>(a);
    } else {
        launch_fwd_dtype<half, kLayout>(a);
    }
}
